insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 6, 'മുനാഫിഖിന്റെ മരണത്തിന് ശക്തിയായ കാറ്റടിച്ചു', 'بَابٌ: بَعْثُ الرِّيحِ الشَّدِيدَةِ لِمَوْتِ الْمُنَافِقِ', 1019 from books where volume_id=2 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 7, 'ഖിയാമത് നാളിൽ കപടവിശ്വാസികൾക്കുള്ള കഠിന ശിക്ഷ', 'بَابٌ: شِدَّةُ عَذَابِ الْمُنَافِقِينَ يَوْمَ الْقِيَامَةِ', 1020 from books where volume_id=2 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 8, 'മുർതദ്ദായ മുനാഫിഖിനെ ഭൂമി എടുത്തെറിയും', 'بَابٌ: فِي نَبْذِ الْأَرْضِ الْمُنَافِقَ الْمُرْتَدَّ وَتَرْكِهِ مَنْبُوذًا', 1020 from books where volume_id=2 and book_no=15 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
