insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ أَصَابَ النَّاسَ فِيهِ شِدَّةٌ، فَقَالَ عَبْدُ اللَّهِ بْنُ أُبَيٍّ لِأَصْحَابِهِ: {لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ حَتَّى يَنْفَضُّوا مِنْ حَوْلِهِ}. قَالَ زُهَيْرٌ: وَهِيَ قِرَاءَةُ مَنْ خَفَضَ حَوْلَهُ. وَقَالَ: {لَئِنْ رَجَعْنَا إِلَى الْمَدِينَةِ لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ} قَالَ: فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ بِذَلِكَ، فَأَرْسَلَ إِلَى عَبْدِ اللَّهِ بْنِ أُبَيٍّ فَسَأَلَهُ، فَاجْتَهَدَ يَمِينَهُ مَا فَعَلَ، فَقِيلَ: كَذَبَ زَيْدٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَوَقَعَ فِي نَفْسِي مِمَّا قَالُوهُ شِدَّةٌ، حَتَّى أَنْزَلَ اللَّهُ تَصْدِيقِي {إِذَا جَاءَكَ الْمُنَافِقُونَ}. قَالَ: ثُمَّ دَعَاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيَسْتَغْفِرَ لَهُمْ. قَالَ: فَلَوَّوْا رُءُوسَهُمْ، وَقَوْلُهُ: {كَأَنَّهُمْ خُشُبٌ مُسَنَّدَةٌ}. قَالَ: كَانُوا رِجَالًا أَجْمَلَ شَيْءٍ. (م)', 'സൈദുബ്നു അർഖം(റ): ഞങ്ങൾ തിരുദൂതർ(സ)യോടുകൂടെ ഒരു യാത്ര പുറപ്പെട്ടു. ജനങ്ങൾക്ക് ആ യാത്രയിൽ ചില വിഷമങ്ങളുണ്ടായി, അപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉബയ്യ് തന്റെ അനുയായികളോട് പറഞ്ഞു: തിരുദൂതർ(സ)യുടെ അടുത്തുളള ആളുകൾക്ക്, റസൂലിനടുത്ത് നിന്നും പിരിഞ്ഞ് പോകുന്നതുവരെ ഒന്നും നൽകരുത്. സുഹൈർ പറഞ്ഞു: ''ഹൗലഹു'' എന്ന പദം ''മിൻഹൗലിഹി'' എന്നോതൽ ''ജർറ്''(ഇകാരം) നൽകിയവരുടെ ഖിറാഅത്താണ് (തജ്‌വീദനുസരിച്ച്). അബ്ദുല്ലാഹിബ്നു ഉബയ്യ് പറഞ്ഞു: ''നാം മദീനയിലേക്ക് മടങ്ങിയാൽ തീർച്ചയായും അവിടുത്തെ മാന്യൻമാർ അവിടുത്തെ നീചരെ പുറത്ത് ചാടിക്കും.'' സൈദ്(റ) പറയുന്നു: അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുത്തുചെന്ന് വിവരം പറഞ്ഞു. തിരുദൂതർ(സ) ഇബ്നുഉബയ്യിനടുത്തേക്ക് ആളെ അയച്ച് അദ്ദേഹം പറഞ്ഞതിനെപ്പറ്റിയന്വേഷിച്ചു, അപ്പോഴദ്ദേഹം അങ്ങനെ പറഞ്ഞത് നിഷേധിച്ചു. സൈദ് തിരുദൂതരോട് കളവ് പറഞ്ഞിരിക്കുന്നു എന്ന് ചിലയാളുകൾ പറയാൻ തുടങ്ങി. സൈദ്(റ) പറയുന്നു: അവരങ്ങനെ പറഞ്ഞതിൽ എനിക്ക് വല്ലാത്ത വിഷമം തോന്നി, അങ്ങനെ എന്റെ സത്യസന്ധതയിൽ അല്ലാഹു, ''മുനാഫിഖുകൾ വന്നാൽ'' എന്ന് തുടങ്ങുന്ന സൂക്തങ്ങളവതരിപ്പിച്ചു. പിന്നെ അവർക്കുവേണ്ടി പൊറുക്കലിനെ തേടാൻ വേണ്ടി അവരെ റസൂൽ(സ) വിളിച്ചു. അപ്പോഴവർ (അഹങ്കാരം കാരണം) അവരുടെ തല തിരിച്ചുകളഞ്ഞു. ''അവർ ചാരിവെക്കപ്പെട്ട മരത്തടികളെപ്പോലെയാകുന്നു'' എന്ന് പറഞ്ഞത്: അവർ ശരീരത്തിലും കാഴ്ചയിലും സുന്ദരൻമാരായിരുന്നു എന്ന് സൂചിപ്പിക്കാനാണ്. (മു)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1017, 1017, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَصْعَدُ الثَّنِيَّةَ ثَنِيَّةَ الْمِرَارِ؟ فَإِنَّهُ يُحَطُّ عَنْهُ مَا حُطَّ عَنْ بَنِي إِسْرَائِيلَ". قَالَ: فَكَانَ أَوَّلَ مَنْ صَعِدَهَا خَيْلُنَا خَيْلُ بَنِي الْخَزْرَجِ ثُمَّ تَتَامَّ النَّاسُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَكُلُّكُمْ مَغْفُورٌ لَهُ إِلَّا صَاحِبَ الْجَمَلِ الْأَحْمَرِ". فَأَتَيْنَاهُ، فَقُلْنَا: تَعَالَ يَسْتَغْفِرْ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: وَاللَّهِ لَأَنْ أَجِدَ ضَالَّتِي أَحَبُّ إِلَيَّ مِنْ أَنْ يَسْتَغْفِرَ لِي صَاحِبُكُمْ. قَالَ: وَكَانَ رَجُلٌ يَنْشُدُ ضَالَّةً لَهُ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ കയ്പ് മരമുള്ള മലഞ്ചെരുവിൽ ആരാണ് കയറുക? (അത് ഹുദൈബിയ്യക്കടുത്താണ്). എന്നാൽ നിശ്ചയമായും ബനൂ ഇസ്റാഈലുകാരെത്തൊട്ട് മാറ്റപ്പെട്ടതെല്ലാം (ശിക്ഷയും നാശവും) അവനെത്തൊട്ടും മാറ്റപ്പെടും." അപ്പോൾ അതിൽ ആദ്യമായി കയറിയത് ഞങ്ങളുടെ അഥവാ ബനു ഖസ്റജിന്റെ കുതിരയായിരുന്നു. പിന്നെ ജനങ്ങളെല്ലാവരും കയറി. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "ആ ചുവന്ന ഒട്ടകത്തിന്റെ ആളൊഴികെ എല്ലാവരും പാപം പൊറുക്കപ്പെട്ടവരാണ്." അങ്ങനെ ഞങ്ങൾ അദ്ദേഹത്തിന്റെയടുത്ത് ചെന്ന് പറഞ്ഞു: നീ വരിക, തിരുദൂതർ(സ) നിനക്ക് വേണ്ടി പാപമോചനം നടത്തിയേക്കും. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു തന്നെയാണ് സത്യം, നിങ്ങളുടെ നേതാവ് എനിക്ക് വേണ്ടി പാപമോചനം തേടുന്നതിനേക്കാൾ എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ടത് എന്റെ കളഞ്ഞുപോയ സാധനം ലഭിക്കലാണ്. ജാബിർ(റ) പറയുന്നു: അദ്ദേഹം തനിക്ക് നഷ്ടപ്പെട്ട ഒരു സാധനം തിരയുകയായിരുന്നു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1018, 1018, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ قَيْسِ بْنِ عُبَادٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ لِعَمَّارٍ: أَرَأَيْتَ قِتَالَكُمْ، أَرَأْيًا رَأَيْتُمُوهُ، فَإِنَّ الرَّأْيَ يُخْطِئُ وَيُصِيبُ، أَوْ عَهْدًا عَهِدَهُ إِلَيْكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: مَا عَهِدَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا لَمْ يَعْهَدْهُ إِلَى النَّاسِ كَافَّةً. وَقَالَ: إِنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ فِي أُمَّتِي...". قَالَ شُعْبَةُ: وَأَحْسِبُهُ قَالَ: حَدَّثَنِي حُذَيْفَةُ. وَقَالَ غُنْدَرٌ: أَرَاهُ قَالَ: "فِي أُمَّتِي اثْنَا عَشَرَ مُنَافِقًا لَا يَدْخُلُونَ الْجَنَّةَ، وَلَا يَجِدُونَ رِيحَهَا حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ، ثَمَانِيَةٌ مِنْهُمْ تَكْفِيكَهُمُ الدُّبَيْلَةُ: سِرَاجٌ مِنَ النَّارِ يَظْهَرُ فِي أَكْتَافِهِمْ حَتَّى يَنْجُمَ مِنْ صُدُورِهِمْ". (م)', 'ഖൈസുബ്നു ഉബാദ്(റ): ഞാൻ അമ്മാർ(റ)വിനോട് ചോദിച്ചു: നിങ്ങൾ ചെയ്ത യുദ്ധത്തെക്കുറിച്ചെന്നോട് പറഞ്ഞുതരുമോ? അത് നിങ്ങളുടെ സ്വന്തം അഭിപ്രായമായിരുന്നോ? നിശ്ചയമായും അഭിപ്രായം ശരിയാകുകയോ, തെറ്റാകുകയോ ചെയ്യാം, അതോ റസൂൽ(സ) നിങ്ങളോട് ചെയ്ത ഏതെങ്കിലും കരാറനുസരിച്ചായിരുന്നോ? അമ്മാർ(റ) പറഞ്ഞു: റസൂൽ(സ) മുഴുവൻ ജനങ്ങൾക്കും നൽകാത്ത ഒരു കരാറും ഞങ്ങളോട് ചെയ്തിട്ടില്ല. എന്നിട്ട് അദ്ദേഹം "നിശ്ചയമായും എന്റെ സമുദായത്തിൽ...." എന്ന നബി(സ)യുടെ ഹദീസ് പറഞ്ഞു. ശുഅ്ബ(റ) പറഞ്ഞു: ഹുദൈഫ(റ) പറഞ്ഞ ഹദീസാണ് അദ്ദേഹം പറഞ്ഞതെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. ഗുൻദർ എന്നവർ പറഞ്ഞു: അദ്ദേഹം പറഞ്ഞത് "എന്റെ സമുദായത്തിൽ 12 മുനാഫിക്കുകളുണ്ട്, ഒട്ടകം സൂചിയുടെ ദ്വാരത്തിലൂടെ പ്രവേശിക്കുന്നത് വരെ അവർ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയോ, അതിന്റെ വാസന എത്തിക്കുകയോ ചെയ്തില്ല. അവരിൽ നിന്ന് എട്ട് പേർക്കുമുള്ള വിഭവം ദുബൈലയായിരിക്കും. ദുബൈലയെന്നാൽ, തീയിനാലുള്ള ഒരു വിളക്കാണ്. അത് അവരുടെ നെഞ്ചിലൂടെ പൊങ്ങുന്നത് വരെ അവരുടെ ചുമലുകളിൽ പ്രത്യക്ഷമായിരിക്കും." എന്ന ഹദീസാണെന്നാണ് ഞാൻ മനസ്സിലാക്കുന്നത്. (മു)', 'قَيْسِ بْنِ عُبَادٍ', 'ഖൈസുബ്നു ഉബാദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1018, 1019, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي الطُّفَيْلِ قَالَ: كَانَ بَيْنَ رَجُلٍ مِنْ أَهْلِ الْعَقَبَةِ وَبَيْنَ حُذَيْفَةَ بَعْضُ مَا يَكُونُ بَيْنَ النَّاسِ، فَقَالَ: أَنْشُدُكَ بِاللهِ، كَمْ كَانَ أَصْحَابُ الْعَقَبَةِ؟ قَالَ: فَقَالَ لَهُ الْقَوْمُ: أَخْبِرْهُ إِذْ سَأَلَكَ. قَالَ: كُنَّا نُخْبَرُ أَنَّهُمْ أَرْبَعَةَ عَشَرَ، فَإِنْ كُنْتَ مِنْهُمْ فَقَدْ كَانَ الْقَوْمُ خَمْسَةَ عَشَرَ، وَأَشْهَدُ بِاللهِ أَنَّ اثْنَيْ عَشَرَ مِنْهُمْ حَرْبٌ لِلَّهِ وَلِرَسُولِهِ فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ يَقُومُ الْأَشْهَادُ، وَعُذِرَ ثَلَاثَةٌ، قَالُوا: مَا سَمِعْنَا مُنَادِيَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَا عَلِمْنَا بِمَا أَرَادَ الْقَوْمُ، وَقَدْ كَانَ فِي حَرَّةٍ فَمَشَى فَقَالَ: "إِنَّ الْمَاءَ قَلِيلٌ، فَلَا يَسْبِقَنِي إِلَيْهِ أَحَدٌ". فَوَجَدَ قَوْمًا قَدْ سَبَقُوهُ فَلَعَنَهُمْ يَوْمَئِذٍ. (م)', 'അബൂത്തുഫൈൽ(റ): അഖബ ഉടമ്പടിയിൽ പങ്കെടുത്ത ഒരാളുടെയും ഹുദൈഫ(റ)വിന്റെയും ഇടയിൽ സാധാരണ ജനങ്ങൾക്കിടയിലുണ്ടാകുന്ന പോലെ, ചില സംസാരമുണ്ടായി. അയാൾ ചോദിച്ചു: അല്ലാഹുവിനെ മുൻനിർത്തി നിന്നോട് ഞാൻ ചോദിക്കുന്നു: ''അഖബ''യിൽ പങ്കെടുത്ത ആളുകളെത്രയായിരുന്നു? അപ്പോൾ ഹുദൈഫ(റ)വിനോട് ആളുകൾ പറഞ്ഞു: നിന്നോട് ചോദിച്ച സ്ഥിതിക്ക് അയാൾക്ക് നിങ്ങൾ പറഞ്ഞുകൊടുക്കുക. ഹുദൈഫ(റ) പറഞ്ഞു: അവർ പതിനാല് പേരാണെന്നാണ് ഞങ്ങൾക്ക് കിട്ടിയ വിവരം. നീ അവരിൽ പെട്ടവനാണെങ്കിൽ മൊത്തം പതിനഞ്ച് പേരായി. ഞാൻ അല്ലാഹുവിനെക്കൊണ്ട് സാക്ഷ്യം വഹിക്കുന്നു, അവരിൽ നിന്നും പന്ത്രണ്ട് പേർ ദുൻയാവിലും സാക്ഷിനിൽക്കുന്ന നാളിലും അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും ശത്രുക്കളാണ്. റസൂൽ(സ)യുടെ വിളി ഞങ്ങൾ കേട്ടില്ലെന്നും, ജനങ്ങൾ എന്താണുദ്ദേശിച്ചതെന്ന് ഞങ്ങളറിഞ്ഞില്ലെന്നും പറഞ്ഞ മൂന്നുപേരെ കുറ്റത്തിൽ നിന്നൊഴിവാക്കി. അത് (അഖബ) കറുത്ത കല്ലുകൾ നിറഞ്ഞ ഒരു സ്ഥലത്തായിരുന്നു, അങ്ങനെ റസൂൽ(സ) നടന്നു, പിന്നെ പറഞ്ഞു: "വെള്ളം കുറവാണ്, അതുകൊണ്ട്, എനിക്ക് മുന്നെ ഒരാളും അതിനടുത്തേക്ക് ചെല്ലരുത്." പക്ഷേ, അവിടുത്തെ മുൻകടന്ന ചിലയാളുകളെ അവിടുന്ന് കാണുകയും അവരെ അന്ന് ശപിക്കുകയും ചെയ്തു. (മു)', 'أَبِي الطُّفَيْلِ قَالَ', 'അബൂത്തുഫൈൽ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1019, 1019, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ الْعَائِرَةِ بَيْنَ الْغَنَمَيْنِ، تَعِيرُ إِلَى هَذِهِ مَرَّةً وَإِلَى هَذِهِ مَرَّةً". (م)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "കപടവിശ്വാസിയുടെ ഉപമ, രണ്ട് ആടുകൾക്കിടയിൽ ചുറ്റിക്കളിക്കുന്ന ആട് പോലെയാണ്, ഒരു പ്രാവശ്യം ഇതിനടുത്തേക്ക് ചെല്ലും, വേറൊരു പ്രാവശ്യം മറ്റേതിനടുത്തേക്ക് ചെല്ലും." (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1019, 1019, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِمَ مِنْ سَفَرٍ، فَلَمَّا كَانَ قُرْبَ الْمَدِينَةِ هَاجَتْ رِيحٌ شَدِيدَةٌ تَكَادُ أَنْ تَدْفِنَ الرَّاكِبَ، فَزَعَمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بُعِثَتْ هَذِهِ الرِّيحُ لِمَوْتِ مُنَافِقٍ". فَلَمَّا قَدِمَ الْمَدِينَةَ فَإِذَا مُنَافِقٌ عَظِيمٌ مِنَ الْمُنَافِقِينَ قَدْ مَاتَ. (م)', 'ജാബിർ(റ): തിരുദൂതർ(സ) ഒരു യാത്ര കഴിഞ്ഞുവന്നു, അങ്ങനെ മദീനയോടടുത്തപ്പോൾ യാത്രക്കാരെ പൊതിയുമാറുള്ള ശക്തിയായൊരു കാറ്റടിച്ചു. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "ഒരു മുനാഫിഖിന്റെ മരണം മൂലമാണ് കാറ്റ് അയക്കപ്പെട്ടത്." അങ്ങനെ മദീനയിലെത്തിയപ്പോഴതാ മുനാഫിഖുകളുടെ വലിയൊരു നേതാവ് മരണപ്പെട്ടിരിക്കുന്നു. (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1019, 1020, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ؛ قَالَ: عُدْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مَوْعُوكًا، قَالَ: فَوَضَعْتُ يَدِي عَلَيْهِ فَقُلْتُ: وَاللَّهِ مَا رَأَيْتُ كَالْيَوْمِ رَجُلًا أَشَدَّ حَرًّا. فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُخْبِرُكُمْ بِأَشَدَّ حَرًّا مِنْهُ يَوْمَ الْقِيَامَةِ؟ هَذَيْنِكَ الرَّجُلَيْنِ الرَّاكِبَيْنِ الْمُقَفَّيَيْنِ". لِرَجُلَيْنِ حِينَئِذٍ مِنْ أَصْحَابِهِ. (م)', 'സലമതുബ്നുൽ അക്വഅ്(റ): ഞങ്ങൾ തിരുദൂതർ(സ)യോടുകൂടെ പനി ബാധിച്ചൊരു മനുഷ്യനെ സന്ദർശിച്ചു. ഞാനെന്റെ കൈ അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ വെച്ച് പറഞ്ഞു: ഇയാളേക്കാൾ കൂടുതൽ ചൂടുള്ള ഒരാളെ ഇന്നുവരെയും ഞാൻ കണ്ടിട്ടില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അന്ത്യദിനത്തിൽ ഇയാളേക്കാൾ ശക്തിയായ ചൂടനുഭവിക്കുന്ന ആളെക്കുറിച്ച് നിങ്ങൾക്ക് ഞാനറിയിച്ച് തരട്ടെയോ?" തന്റെ സ്വഹാബികൾക്കിടയിലുണ്ടായിരുന്ന രണ്ടാളുകളെക്കാണിച്ച് റസൂൽ(സ) പറഞ്ഞു: "അതാ, യാത്രക്കാരായ, പിരടി തിരിച്ചിരിക്കുന്ന ആ രണ്ടാളുകളാണ്." (മു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1020, 1020, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ مِنَّا رَجُلٌ مِنْ بَنِي النَّجَّارِ، قَدْ قَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ، وَكَانَ يَكْتُبُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَانْطَلَقَ هَارِبًا حَتَّى لَحِقَ بِأَهْلِ الْكِتَابِ، قَالَ: فَرَفَعُوهُ، قَالُوا: هَذَا قَدْ كَانَ يَكْتُبُ لِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأُعْجِبُوا بِهِ، فَمَا لَبِثَ أَنْ قَصَمَ اللَّهُ عُنُقَهُ فِيهِمْ، فَحَفَرُوا لَهُ فَوَارَوْهُ، فَأَصْبَحَتِ الْأَرْضُ قَدْ نَبَذَتْهُ عَلَى وَجْهِهَا، ثُمَّ عَادُوا فَحَفَرُوا لَهُ فَوَارَوْهُ، فَأَصْبَحَتِ الْأَرْضُ قَدْ نَبَذَتْهُ عَلَى وَجْهِهَا، ثُمَّ عَادُوا فَحَفَرُوا لَهُ فَوَارَوْهُ، فَأَصْبَحَتِ الْأَرْضُ قَدْ نَبَذَتْهُ عَلَى وَجْهِهَا، فَتَرَكُوهُ مَنْبُوذًا. (م)', 'അനസുബ്നു മാലിക്(റ): ഞങ്ങളുടെ കൂട്ടത്തിൽ ബനൂന്നജ്ജാറിൽ പെട്ട ഒരാളുണ്ടായിരുന്നു. സൂറതുൽ ബഖറയും സൂറതു ആലുഇംറാനും അദ്ദേഹം പാരായണം ചെയ്തിട്ടുണ്ട്. അദ്ദേഹം തിരുദൂതർ(സ)ക്ക് വേണ്ടി എഴുതാറുണ്ടായിരുന്നു. അങ്ങനെ അദ്ദേഹം ഓടിപ്പോയി വേദക്കാരോടൊപ്പം ചേർന്നു. അനസ്(റ) പറയുന്നു: ഇയാൾ തിരുദൂതർ(സ)ക്ക് വേണ്ടി എഴുതിയിരുന്ന ആളാണെന്ന് പറഞ്ഞ് അവർ അദ്ദേഹത്തിന് ഉന്നതസ്ഥാനം നൽകുകയും അദ്ദേഹത്താൽ സന്തുഷ്ടരാവുകയും ചെയ്തു. അധികം താമസിയാതെ അല്ലാഹു അവരിൽ വെച്ചുതന്നെ അയാളെ നശിപ്പിച്ചു. അങ്ങനെ അവർ കുഴികുഴിച്ച് അയാളെ മറവുചെയ്തു. അപ്പോൾ തന്നെ ഭൂമി അയാളെ പുറത്തേക്കെടുത്തെറിഞ്ഞു. പിന്നെ അവർ മടങ്ങിവന്ന് വീണ്ടും കുഴിച്ച് അയാളെ മറവുചെയ്തു. അപ്പോഴും ഭൂമി അയാളെ എടുത്തെറിഞ്ഞു, വീണ്ടും കുഴിച്ച് മറവ് ചെയ്തു. അപ്പോഴും ഭൂമി എടുത്തെറിഞ്ഞു; അപ്പോൾ അവർ അയാളെ എറിയപ്പെട്ട നിലയിൽ തന്നെ ഉപേക്ഷിച്ചു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 1020, 1020, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
